<?php
declare(strict_types=1);

namespace App\Controllers;

use App\Models\{LiteratureEvidence, LiteratureSource, ProjectLiterature, SourceVerificationRecord};
use App\Policies\ProjectAccess;
use App\Services\AuditLogger;
use App\Support\{Database, HttpException, Request, Response};

/**
 * Literature register. Sources are entered by people; nothing here is generated by AI, and a source is only
 * "verified" when a human records a verification (the system never invents or auto-verifies references).
 */
final class LiteratureController extends BaseController
{
    private function present(array $row): array
    {
        $s = LiteratureSource::find((int) $row['source_id']);
        $last = Database::fetchOne('SELECT r.method, r.outcome, r.notes, r.created_at, u.first_name, u.last_name FROM source_verification_records r LEFT JOIN users u ON u.id = r.verified_by WHERE r.source_id = ? ORDER BY r.id DESC LIMIT 1', [$s['id']]);
        return [
            'id' => $s['uuid'], 'title' => $s['title'], 'authors' => $s['authors'], 'year' => $s['publication_year'], 'venue' => $s['venue'], 'doi' => $s['doi'], 'url' => $s['url'],
            'source_type' => $s['source_type'], 'literature_type' => $row['literature_type'], 'theme' => $row['theme'], 'relevance_notes' => $row['relevance_notes'],
            'verification_status' => $s['verification_status'],
            'last_verification' => $last ? ['method' => $last['method'], 'outcome' => $last['outcome'], 'notes' => $last['notes'], 'at' => $last['created_at'], 'by' => trim(($last['first_name'] ?? '') . ' ' . ($last['last_name'] ?? ''))] : null,
        ];
    }

    public function index(Request $r): Response
    {
        $project = $this->project($r, 'project.viewDetails');
        $rows = ProjectLiterature::where(['project_id' => $project['id']], 'id DESC');
        return $this->ok(array_map([$this, 'present'], $rows), ['notice' => 'References are entered and verified by people. The AI never creates or verifies references.']);
    }

    public function store(Request $r): Response
    {
        $project = $this->project($r, 'project.update');
        $user = $this->user($r);
        $d = $this->validate($r, [
            'title' => 'required|string|max:500', 'authors' => 'required|string|max:500', 'year' => 'nullable|int|min:1500|max:2100', 'venue' => 'nullable|string|max:300',
            'doi' => 'nullable|string|max:200|regex:/^10\.\d{4,9}\/\S+$/', 'url' => 'nullable|string|max:500|regex:/^https?:\/\//i',
            'source_type' => 'nullable|in:journal,book,chapter,thesis,report,conference,web,other', 'literature_type' => 'nullable|in:theoretical,empirical,methodological,other',
            'theme' => 'nullable|string|max:255', 'relevance_notes' => 'nullable|string|max:5000',
        ]);
        $source = !empty($d['doi']) ? LiteratureSource::first(['institution_id' => $project['institution_id'], 'doi' => strtolower($d['doi'])]) : null;
        if (!$source) {
            $sid = LiteratureSource::create([
                'institution_id' => $project['institution_id'], 'title' => $d['title'], 'authors' => $d['authors'], 'publication_year' => $d['year'] ?? null, 'venue' => $d['venue'] ?? null,
                'doi' => isset($d['doi']) ? strtolower($d['doi']) : null, 'url' => $d['url'] ?? null, 'source_type' => $d['source_type'] ?? 'journal', 'created_by' => $user['id'],
            ]);
            $source = LiteratureSource::find($sid);
        }
        if (ProjectLiterature::first(['project_id' => $project['id'], 'source_id' => $source['id']])) {
            throw HttpException::conflict('This source is already in the project literature.');
        }
        $id = ProjectLiterature::create(['project_id' => $project['id'], 'source_id' => $source['id'], 'theme' => $d['theme'] ?? null, 'literature_type' => $d['literature_type'] ?? 'empirical', 'relevance_notes' => $d['relevance_notes'] ?? null, 'added_by' => $user['id']]);
        AuditLogger::log($r, 'literature.add', 'literature_source', $source['uuid'], ['project' => $project['uuid']]);
        return $this->created($this->present(ProjectLiterature::find($id)));
    }

    private function link(Request $r, array $project): array
    {
        $s = LiteratureSource::findByUuid((string) $r->param('sid'));
        $link = $s ? ProjectLiterature::first(['project_id' => $project['id'], 'source_id' => $s['id']]) : null;
        if (!$link) {
            throw HttpException::notFound('Source');
        }
        return [$s, $link];
    }

    public function destroy(Request $r): Response
    {
        $project = $this->project($r, 'project.update');
        [, $link] = $this->link($r, $project);
        ProjectLiterature::deleteById((int) $link['id']);
        return $this->ok(['removed' => true]);
    }

    /** A person records the result of checking the source (e.g. DOI lookup, library catalogue). */
    public function verify(Request $r): Response
    {
        $project = $this->project($r, 'project.update');
        $user = $this->user($r);
        [$s] = $this->link($r, $project);
        $d = $this->validate($r, ['method' => 'required|in:doi_lookup,library_catalogue,manual_inspection,publisher_site', 'outcome' => 'required|in:verified,not_found,mismatch', 'notes' => 'nullable|string|max:3000']);
        SourceVerificationRecord::create(['source_id' => $s['id'], 'verified_by' => $user['id'], 'method' => $d['method'], 'outcome' => $d['outcome'], 'notes' => $d['notes'] ?? null]);
        LiteratureSource::updateById((int) $s['id'], ['verification_status' => $d['outcome'] === 'verified' ? 'verified' : 'rejected']);
        AuditLogger::log($r, 'literature.verify', 'literature_source', $s['uuid'], ['project' => $project['uuid'], 'outcome' => $d['outcome']]);
        return $this->ok($this->present(ProjectLiterature::first(['project_id' => $project['id'], 'source_id' => $s['id']])));
    }

    public function evidence(Request $r): Response
    {
        $project = $this->project($r, 'project.viewDetails');
        $rows = LiteratureEvidence::where(['project_id' => $project['id']], 'id DESC', 200);
        return $this->ok(array_map(fn($e) => ['id' => $e['uuid'], 'type' => $e['evidence_type'], 'excerpt' => $e['excerpt'], 'page' => $e['page_number'], 'notes' => $e['notes'], 'origin' => $e['origin'], 'source' => $e['source_id'] ? (LiteratureSource::find((int) $e['source_id'])['uuid'] ?? null) : null], $rows));
    }

    public function addEvidence(Request $r): Response
    {
        $project = $this->project($r, 'project.update');
        $user = $this->user($r);
        $d = $this->validate($r, ['source_id' => 'nullable|uuid', 'evidence_type' => 'required|in:theory,empirical,methodological,gap_claim,other', 'excerpt' => 'required|string|max:5000', 'page' => 'nullable|int|min:1', 'notes' => 'nullable|string|max:3000']);
        $src = null;
        if (!empty($d['source_id'])) {
            $src = LiteratureSource::findByUuid($d['source_id']);
            if (!$src || !ProjectLiterature::first(['project_id' => $project['id'], 'source_id' => $src['id']])) {
                throw HttpException::unprocessable('Unknown source.', ['source_id' => ['Add the source to the project literature first.']]);
            }
        }
        $id = LiteratureEvidence::create(['project_id' => $project['id'], 'source_id' => $src['id'] ?? null, 'evidence_type' => $d['evidence_type'], 'excerpt' => $d['excerpt'], 'page_number' => $d['page'] ?? null, 'notes' => $d['notes'] ?? null, 'origin' => ProjectAccess::has($user, $project, 'supervisor') ? 'supervisor' : 'student']);
        return $this->created(['id' => LiteratureEvidence::find($id)['uuid']]);
    }
}
